-- Disposable database only, after the competition migration; every test change rolls back.
begin;
do $$ declare
  secret text:=repeat('test-only-',5);
  a uuid;b uuid;k1 uuid;k2 uuid; judge1 uuid;judge2 uuid; noteid uuid;
  result jsonb; scores jsonb; accepted boolean;
begin
  if exists(select 1 from qoq_private.settings) then raise exception 'Run on a clean test database only'; end if;
  if has_schema_privilege('anon','qoq_private','USAGE') or has_table_privilege('authenticated','qoq_private.scores','SELECT') or has_table_privilege('anon','qoq_private.settings','SELECT')
     or has_function_privilege('authenticated','public.qoq_operations(text,text,text,boolean,text,jsonb)','EXECUTE') then raise exception 'Unexpected public grants'; end if;
  insert into qoq_private.settings(secret_hash) values (encode(sha256(convert_to(secret,'utf8')),'hex'));
  begin perform public.qoq_operations('wrong',null,null,false,'public.voting','{}'); raise exception 'Bad secret was accepted'; exception when insufficient_privilege then null; end;
  begin perform public.qoq_operations(secret,'someone','someone@example.invalid',false,'organizer.dashboard','{}'); raise exception 'Non-organizer got dashboard'; exception when insufficient_privilege then null; end;
  if public.qoq_operations(secret,'','',false,'public.voting','{}')<> '{"voting":"closed","candidates":[]}'::jsonb then raise exception 'Voting leaked roster';end if;
  begin perform public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.openVoting','{}'); raise exception 'Empty voting opened'; exception when object_not_in_prerequisite_state then null; end;
  begin perform public.qoq_operations(secret,'intruder','i@example.invalid',false,'judge.ballot','{}'); raise exception 'Unassigned judge got ballot'; exception when insufficient_privilege then null; end;
  a:=(public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.candidate','{"name":"Candidate A","photoKey":"9800a230-90d4-4fb0-82b5-83b855757eae"}')->>'id')::uuid;
  b:=(public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.candidate','{"name":"Candidate B"}')->>'id')::uuid;
  judge1:=(public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.judge','{"name":"Judge 1","email":"J1@example.invalid"}')->>'id')::uuid;
  judge2:=(public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.judge','{"name":"Judge 2","email":"j2@example.invalid"}')->>'id')::uuid;
  k1:=(public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.criterion','{"name":"First","weight":60}')->>'id')::uuid;
  begin perform public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.openScoring','{}'); raise exception 'Bad weights accepted'; exception when object_not_in_prerequisite_state then null; end;
  k2:=(public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.criterion','{"name":"Second","weight":40}')->>'id')::uuid;
  result:=public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.candidate','{"name":"Remove me"}');
  perform public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.remove',jsonb_build_object('kind','candidate','id',result->>'id'));
  noteid:=(public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.announcement','{"title":"A","body":"Draft","published":false}')->>'id')::uuid;
  if public.qoq_operations(secret,'','',false,'public.announcements','{}')->'announcements'<>'[]'::jsonb then raise exception 'Private draft leaked';end if;
  perform public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.announcement',jsonb_build_object('id',noteid,'title','A','body','Published','published',true));
  if jsonb_array_length(public.qoq_operations(secret,'','',false,'public.announcements','{}')->'announcements')<>1 then raise exception 'Published announcement absent';end if;
  begin perform public.qoq_operations(secret,'','',false,'public.photo','{"photoKey":"9800a230-90d4-4fb0-82b5-83b855757eae"}');raise exception 'Unpublished photo available';exception when insufficient_privilege then null;end;
  perform public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.openVoting','{}');
  perform public.qoq_operations(secret,'','',false,'public.photo','{"photoKey":"9800a230-90d4-4fb0-82b5-83b855757eae"}');
  begin perform public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.candidate','{"name":"Late entry"}');raise exception 'Roster changed during voting';exception when object_not_in_prerequisite_state then null;end;
  begin perform public.qoq_operations(secret,'','',false,'voter.cast',jsonb_build_object('candidateId',a));raise exception 'Anonymous vote';exception when insufficient_privilege then null;end;
  perform public.qoq_operations(secret,'voter','v@example.invalid',false,'voter.cast',jsonb_build_object('candidateId',a));
  begin perform public.qoq_operations(secret,'voter','changed@example.invalid',false,'voter.cast',jsonb_build_object('candidateId',b));raise exception 'Same account twice';exception when unique_violation then null;end;
  begin perform public.qoq_operations(secret,'other-voter','V@EXAMPLE.INVALID',false,'voter.cast',jsonb_build_object('candidateId',b));raise exception 'Same verified email twice';exception when unique_violation then null;end;
  perform public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.closeVoting','{}');
  begin perform public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.openVoting','{}');raise exception 'Reopened ended voting';exception when object_not_in_prerequisite_state then null;end;
  begin perform public.qoq_operations(secret,'other','other@example.invalid',false,'voter.cast',jsonb_build_object('candidateId',b));raise exception 'Late vote';exception when object_not_in_prerequisite_state then null;end;
  perform public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.openScoring','{}');
  begin perform public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.remove',jsonb_build_object('kind','criterion','id',k1));raise exception 'Changed scoring criteria';exception when object_not_in_prerequisite_state then null;end;
  begin perform public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.lockTabulation','{}');raise exception 'Locked incomplete results';exception when object_not_in_prerequisite_state then null;end;
  result:=public.qoq_operations(secret,'judge-one','j1@example.invalid',false,'judge.ballot','{}');
  if result?'tabulation' or result?'judges' or jsonb_array_length(result->'candidates')<>2 then raise exception 'Incorrect judge scope';end if;
  begin perform public.qoq_operations(secret,'imposter','j1@example.invalid',false,'judge.ballot','{}');raise exception 'Bound account stolen';exception when insufficient_privilege then null;end;
  begin perform public.qoq_operations(secret,'judge-one','j1@example.invalid',false,'judge.lock','{}');raise exception 'Incomplete ballot accepted';exception when object_not_in_prerequisite_state then null;end;
  begin perform public.qoq_operations(secret,'judge-one','j1@example.invalid',false,'judge.save',jsonb_build_object('scores',jsonb_build_array(jsonb_build_object('candidateId',a,'criterionId',k1,'score',101))));raise exception 'Out-of-range score accepted';exception when invalid_parameter_value then null;end;
  scores:=jsonb_build_array(jsonb_build_object('candidateId',a,'criterionId',k1,'score',90),jsonb_build_object('candidateId',a,'criterionId',k2,'score',60),jsonb_build_object('candidateId',b,'criterionId',k1,'score',80),jsonb_build_object('candidateId',b,'criterionId',k2,'score',80));
  perform public.qoq_operations(secret,'judge-one','j1@example.invalid',false,'judge.save',jsonb_build_object('scores',scores));
  result:=public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.dashboard','{}');
  if result#>'{tabulation,results}'<>'[]'::jsonb or result#>'{tabulation,ballots}'<>'[]'::jsonb then raise exception 'Draft scores were disclosed';end if;
  result:=public.qoq_operations(secret,'judge-two','j2@example.invalid',false,'judge.ballot','{}');
  if result->'scores'<>'[]'::jsonb then raise exception 'Other judge scores visible';end if;
  perform public.qoq_operations(secret,'judge-one','j1@example.invalid',false,'judge.lock','{}');
  begin update qoq_private.scores set score=0 where judge_id=judge1;raise exception 'Locked scores edited';exception when object_not_in_prerequisite_state then null;end;
  begin update qoq_private.judges set locked_at=null where id=judge1;raise exception 'Locked judge unlocked';exception when object_not_in_prerequisite_state then null;end;
  result:=public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.dashboard','{}');
  if (result#>>'{tabulation,pending}')::int<>1 or (result#>>'{tabulation,results,0,score}')::numeric<>80 or (result#>>'{tabulation,results,1,score}')::numeric<>78 then raise exception 'Provisional weighted scores wrong: %',result->'tabulation';end if;
  scores:=jsonb_set(scores,'{0,score}','100');
  perform public.qoq_operations(secret,'judge-two','j2@example.invalid',false,'judge.save',jsonb_build_object('scores',scores));
  perform public.qoq_operations(secret,'judge-two','j2@example.invalid',false,'judge.lock','{}');
  perform public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.lockTabulation','{}');
  result:=public.qoq_operations(secret,'owner','o@example.invalid',true,'organizer.dashboard','{}');
  if (result#>>'{tabulation,pending}')::int<>0 or not (result#>>'{tabulation,final}')::boolean or (result#>>'{tabulation,results,0,score}')::numeric<>81 or jsonb_array_length(result#>'{tabulation,ballots}')<>2 then raise exception 'Final weighted scores wrong: %',result->'tabulation';end if;
  begin update qoq_private.settings set phase='scoring' where singleton;raise exception 'Final state reopened';exception when object_not_in_prerequisite_state then null;end;
  begin perform public.qoq_operations(secret,'judge-two','j2@example.invalid',false,'judge.save',jsonb_build_object('scores',scores));raise exception 'Locked ballot edited';exception when object_not_in_prerequisite_state then null;end;
end $$;
rollback;
